**Step 8: Initialize EventPublisher in Service**
```java
// Java Spring Boot example
@Configuration
public class EventPublishingConfig {

    @Bean
    public EventPublisher eventPublisher(
        EventPublisherProperties properties,
        KmsClient kmsClient,
        SecretsManagerClient secretsManager
    ) {
        return EventPublisher.builder()
            .kafkaBootstrapServers(properties.getKafka().getBootstrapServers())
            .oauthConfig(properties.getAuthentication())
            .kmsSigningConfig(properties.getSigning())
            .schemaRegistryUrl(properties.getSchemaRegistry().getUrl())
            .observabilityConfig(properties.getObservability())
            .reliabilityConfig(properties.getReliability())
            .build();
    }
}
```

**Step 9: Implement Event Publishing in Business Logic**
```java
@Service
public class ClaimSubmissionService {

    private final EventPublisher eventPublisher;
    private final Logger logger = LoggerFactory.getLogger(ClaimSubmissionService.class);

    @Autowired
    public ClaimSubmissionService(EventPublisher eventPublisher) {
        this.eventPublisher = eventPublisher;
    }

    public SubmissionResponse submitClaim(ClaimSubmissionRequest request) {
        // Business logic validation
        validateClaim(request);

        // Persist claim to database
        Claim claim = claimRepository.save(request.toClaim());

        // Create domain event
        ClaimSubmittedEvent event = ClaimSubmittedEvent.builder()
            .claimId(claim.getId())
            .memberId(claim.getMemberId())
            .providerNpi(claim.getProviderNpi())
            .serviceDate(claim.getServiceDate())
            .billedAmount(claim.getBilledAmount())
            .build();

        // Publish event asynchronously
        CompletableFuture<PublishResult> publishFuture = eventPublisher.publishAsync(
            "claims.submitted",  // topic
            claim.getId(),       // partition key
            event                // event payload
        );

        // Handle acknowledgment asynchronously (non-blocking)
        publishFuture.whenComplete((result, exception) -> {
            if (exception != null) {
                logger.error("Failed to publish ClaimSubmitted event for claim {}: {}",
                    claim.getId(), exception.getMessage(), exception);
                // Event automatically sent to DLQ by SDK
            } else {
                logger.info("Successfully published ClaimSubmitted event for claim {} " +
                    "with correlation_id={}, offset={}, latency={}ms",
                    claim.getId(), result.getCorrelationId(),
                    result.getOffset(), result.getLatencyMs());
            }
        });

        // Return response immediately (don't wait for Kafka acknowledgment)
        return SubmissionResponse.builder()
            .claimId(claim.getId())
            .status("SUBMITTED")
            .correlationId(eventPublisher.getCurrentCorrelationId())
            .build();
    }
}
```

