@SpringBootTest
class ClaimSubmissionServiceTest {

    @MockBean
    private EventPublisher eventPublisher;

    @Autowired
    private ClaimSubmissionService service;

    @Test
    void testClaimSubmissionPublishesEvent() {
        // Given
        ClaimSubmissionRequest request = createValidRequest();
        when(eventPublisher.publishAsync(anyString(), anyString(), any()))
            .thenReturn(CompletableFuture.completedFuture(
                PublishResult.success("correlation-id-123", 42L, 15L)
            ));

        // When
        SubmissionResponse response = service.submitClaim(request);

        // Then
        assertThat(response.getStatus()).isEqualTo("SUBMITTED");
        assertThat(response.getCorrelationId()).isNotNull();

        verify(eventPublisher).publishAsync(
            eq("claims.submitted"),
            eq(response.getClaimId()),
            argThat(event ->
                event.getClaimId().equals(response.getClaimId()) &&
                event.getMemberId().equals(request.getMemberId())
            )
        );
    }
}
```

**Step 11: Integration Testing Against Test Kafka Cluster**
```java
@SpringBootTest
@Testcontainers
class EventPublishingIntegrationTest {

    @Container
    static KafkaContainer kafka = new KafkaContainer(
        DockerImageName.parse("confluentinc/cp-kafka:7.5.0")
    );

    @Test
    void testEventPublishedToKafka() throws Exception {
        // Setup Kafka consumer to verify event published
        Consumer<String, ClaimSubmittedEvent> consumer = createTestConsumer();
        consumer.subscribe(Collections.singletonList("claims.submitted"));

        // Publish event
