        eventPublisher.publishAsync("claims.submitted", event.getClaimId(), event)
            .get(5, TimeUnit.SECONDS);

        // Verify event received
        ConsumerRecords<String, ClaimSubmittedEvent> records =
            consumer.poll(Duration.ofSeconds(10));

        assertThat(records.count()).isEqualTo(1);
        ClaimSubmittedEvent receivedEvent = records.iterator().next().value();
        assertThat(receivedEvent.getClaimId()).isEqualTo(event.getClaimId());

        // Verify event has authentication headers
