const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { KMSClient } = require('@aws-sdk/client-kms');

class CareServiceEventPublisher {
    constructor() {
        this.publisher = new EventPublisher({
            kafka: {
                brokers: process.env.MSK_BOOTSTRAP_SERVERS.split(','),
                ssl: true,
                sasl: {
                    mechanism: 'aws',
                    authorizationIdentity: process.env.AWS_ROLE_ARN
                },
                clientId: 'care-service-producer'
            },
            authentication: {
                oauthTokenUrl: process.env.OAUTH_TOKEN_URL,
                clientId: process.env.OAUTH_CLIENT_ID,
                clientSecretArn: process.env.OAUTH_CLIENT_SECRET_ARN,
                scope: 'kafka.publish'
            },
            signing: {
                kmsKeyId: process.env.KMS_SIGNING_KEY_ID,
                algorithm: 'RSASSA_PKCS1_V1_5_SHA_256'
            },
            schemaRegistry: {
                url: process.env.SCHEMA_REGISTRY_URL
            },
            reliability: {
                idempotent: true,
                acks: -1, // all
                retries: 3,
                timeout: 30000,
                dlqTopic: 'eaas.dlq.publishing-failures'
            },
            observability: {
                correlationIdHeader: 'x-correlation-id',
                cloudWatchNamespace: 'EaaS/EventPublishing',
                xrayEnabled: true
            }
        });
    }

    async initialize() {
        await this.publisher.connect();
    }

    async publishCareGapIdentified(careGap) {
        const event = {
            care_gap_id: careGap.id,
            member_id: careGap.memberId,
            gap_type: careGap.gapType,
            identified_date: careGap.identifiedDate.toISOString(),
            severity: careGap.severity,
            recommended_action: careGap.recommendedAction
        };

        try {
            const result = await this.publisher.publish({
                topic: 'care.gap-identified',
                key: careGap.memberId,
                value: event
            });

            console.log(`Published CareGapIdentified event: correlation_id=${result.correlationId}, offset=${result.offset}, latency=${result.latencyMs}ms`);
            return result;
        } catch (error) {
            console.error(`Failed to publish CareGapIdentified event: ${error.message}`, error);
            // Event automatically sent to DLQ by SDK
            throw error;
        }
    }

    async shutdown() {
        await this.publisher.disconnect();
    }
}

module.exports = CareServiceEventPublisher;

